```go
package cache

import "container/list"

// LRU is a fixed-capacity Least Recently Used cache.
type LRU struct {
    capacity int
    items    map[string]*list.Element
    list     *list.List
}

// NewLRU creates a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
    return &LRU{
        capacity: capacity,
        items:    make(map[string]*list.Element),
        list:     list.New(),
    }
}

// Get retrieves the value associated with the key.
// If the key exists, it is moved to the front (most recently used).
// Returns the value and true if found, or 0 and false otherwise.
func (c *LRU) Get(key string) (int, bool) {
    if elem, ok := c.items[key]; ok {
        c.list.MoveToFront(elem)
        return elem.Value.(*entry).value, true
    }
    return 0, false
}

// Put adds or updates a key-value pair in the cache.
// If the cache is full, the least recently used item is evicted.
func (c *LRU) Put(key string, value int) {
    if elem, ok := c.items[key]; ok {
        elem.Value.(*entry).value = value
        c.list.MoveToFront(elem)
        return
    }

    // Evict if full
    if c.list.Len() >= c.capacity {
        oldest := c.list.Back()
        if oldest != nil {
            entry := oldest.Value.(*entry)
            delete(c.items, entry.key)
            c.list.Remove(oldest)
        }
    }

    // Add new entry
    entry := &entry{
        key:   key,
        value: value,
    }
    elem := c.list.PushFront(entry)
    c.items[key] = elem
}

// Len returns the number of items in the cache.
func (c *LRU) Len() int {
    return c.list.Len()
}

// entry represents a node in the doubly linked list.
type entry struct {
    key   string
    value int
}
```

